export const meta = {
  name: 'caliper-recall-and-harness',
  description: 'Chakra NonNullable root cause, weekly harness fixes, terminal React builtins, module augmentation, then Pick/keyof/union stacked on builtins; each branch independently reviewed',
  phases: [
    { title: 'Build', detail: 'four independent branches in parallel' },
    { title: 'Stack', detail: 'Pick/keyof/union stacked on the builtins branch' },
    { title: 'Review', detail: 'one independent reviewer per branch' },
