    branch: { type: 'string' },
    base: { type: 'string' },
    commit: { type: 'string', description: 'short sha of the last commit, with its %G? signature letter' },
    pushed: { type: 'boolean' },
    summary: { type: 'string', description: 'what changed and why, 3 to 8 sentences' },
